-- CFOClose Ready-for-Reporting (consolidated 2026-11-12) staged transport bootstrap. GENERATED by scripts/release/rfrStagedTransport.mjs; do not edit.
-- The four sources (20261223100000, 20261224100000, 20261225100000, 20261226100000) are inert until a registered apply executes each once.
DO $cfoclose_rfr_transport_bootstrap$
DECLARE
  c_predecessor CONSTANT text[] := ARRAY['f319b4600a013871c0c734ef4e5a7451becfada0787f88f4a5ca40a80d420294', '9f721b4bbbf326153bdb0a2d4dcc498a411c7c51b1ca65aaeebe2d8a2684aa4c']::text[];
  v_n bigint;
  v_pred_id bigint;
