  CREATE TRIGGER trg_transport_events_no_truncate BEFORE TRUNCATE ON cfoclose_rfr_release.transport_events
    FOR EACH STATEMENT EXECUTE FUNCTION cfoclose_rfr_release.append_only_guard();
  ALTER TABLE cfoclose_rfr_release.staged_artifacts ENABLE ROW LEVEL SECURITY;
  ALTER TABLE cfoclose_rfr_release.transport_events ENABLE ROW LEVEL SECURITY;
  REVOKE ALL ON SCHEMA cfoclose_rfr_release FROM PUBLIC;
  REVOKE ALL ON ALL TABLES IN SCHEMA cfoclose_rfr_release FROM PUBLIC;
  REVOKE ALL ON ALL SEQUENCES IN SCHEMA cfoclose_rfr_release FROM PUBLIC;
  REVOKE EXECUTE ON FUNCTION cfoclose_rfr_release.approved_artifact(text, text) FROM PUBLIC;
  REVOKE EXECUTE ON FUNCTION cfoclose_rfr_release.staged_artifacts_guard() FROM PUBLIC;
  REVOKE EXECUTE ON FUNCTION cfoclose_rfr_release.append_only_guard() FROM PUBLIC;
  FOREACH v_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = v_role) THEN
