      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA cfoclose_rfr_release FROM %I', v_role);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA cfoclose_rfr_release FROM %I', v_role);
      EXECUTE format('REVOKE EXECUTE ON FUNCTION cfoclose_rfr_release.approved_artifact(text, text) FROM %I', v_role);
      EXECUTE format('REVOKE EXECUTE ON FUNCTION cfoclose_rfr_release.staged_artifacts_guard() FROM %I', v_role);
      EXECUTE format('REVOKE EXECUTE ON FUNCTION cfoclose_rfr_release.append_only_guard() FROM %I', v_role);
    END IF;
  END LOOP;
END
